#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

std::vector<int> parent, size_of;

int find(int v) {
    int root = v;
    while (parent[root] != root) root = parent[root];
    while (parent[v] != root) { int next = parent[v]; parent[v] = root; v = next; }
    return root;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, q;
    std::cin >> n >> q;
    parent.resize(n);
    std::iota(parent.begin(), parent.end(), 0);
    size_of.assign(n, 1);

    int components = n;
    for (int i = 0; i < q; ++i) {
        int op;
        std::cin >> op;
        if (op == 1) {
            int u, v;
            std::cin >> u >> v;
            int a = find(u - 1), b = find(v - 1);
            if (a != b) {
                if (size_of[a] < size_of[b]) std::swap(a, b);
                parent[b] = a;
                size_of[a] += size_of[b];
            }
            --components;                    // one per instruction, not per merge
        } else if (op == 2) {
            int u, v;
            std::cin >> u >> v;
            std::cout << (find(u - 1) == find(v - 1) ? "YES" : "NO") << '\n';
        } else {
            std::cout << components << '\n';
        }
    }
}

